// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.json;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.junit.jupiter.api.Test;

/**
 * Edge cases for the JSON input handling and the JSONPath subset shared by all {@code jsonf:} functions.
 */
class JsonInputAndPathEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final List<Function> JSON_INPUT_FUNCTIONS = List.of(new JsonValue(), new JsonQuery(),
			new JsonExists(), new JsonKeys(), new JsonArrayLength(), new JsonSet());

	private static Literal json(String s) {
		return VF.createLiteral(s, CoreDatatype.RDF.JSON);
	}

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	/** Invokes {@code function} with {@code document} as the JSON argument and well-formed remaining arguments. */
	private static void evaluateWithDocument(Function function, Literal document) {
		if (function instanceof JsonSet) {
			function.evaluate(VF, document, str("$.a"), integer(1));
		} else if (function instanceof JsonKeys || function instanceof JsonArrayLength) {
			function.evaluate(VF, document);
		} else {
			function.evaluate(VF, document, str("$.a"));
		}
	}

	// ------------------------------------------------------------------ input handling

	@Test
	void rdfJsonLiteralAndPlainStringHoldingJsonAreEquivalentInputs() {
		String text = "{\"a\":[1,2],\"b\":\"x\"}";
		assertThat(new JsonValue().evaluate(VF, json(text), str("$.b")))
				.isEqualTo(new JsonValue().evaluate(VF, str(text), str("$.b")))
				.isEqualTo(str("x"));
		assertThat(new JsonArrayLength().evaluate(VF, json(text), str("$.a")))
				.isEqualTo(new JsonArrayLength().evaluate(VF, str(text), str("$.a")))
				.isEqualTo(integer(2));
		assertThat(new JsonKeys().evaluate(VF, str(text))).isEqualTo(json("[\"a\",\"b\"]"));
		assertThat(new JsonExists().evaluate(VF, str(text), str("$.a"))).isEqualTo(BooleanLiteral.TRUE);
		// the output datatype is always rdf:JSON, whichever input kind was used
		assertThat(new JsonQuery().evaluate(VF, str(text), str("$.a")).getCoreDatatype())
				.isEqualTo(CoreDatatype.RDF.JSON);
	}

	@Test
	void invalidJsonTextIsAnEvaluationErrorForEveryFunction() {
		for (String invalid : List.of("not json", "{", "[1,]", "{'a':1}", "{\"a\":1} trailing", "[1 2]",
				"{\"a\":tru}", "\"unterminated", "[01]x", "{\"a\":\"\t\"}")) {
			for (Function function : JSON_INPUT_FUNCTIONS) {
				for (Literal document : List.of(json(invalid), str(invalid))) {
					assertThatThrownBy(() -> evaluateWithDocument(function, document))
							.as("%s on %s", function.getURI(), invalid)
							.isInstanceOf(ValueExprEvaluationException.class);
				}
			}
		}
	}

	@Test
	void emptyOrBlankJsonTextIsAnEvaluationError() {
		for (String empty : List.of("", " ", "\n\t")) {
			for (Function function : JSON_INPUT_FUNCTIONS) {
				assertThatThrownBy(() -> evaluateWithDocument(function, json(empty)))
						.as("%s on rdf:JSON '%s'", function.getURI(), empty)
						.isInstanceOf(ValueExprEvaluationException.class);
				assertThatThrownBy(() -> evaluateWithDocument(function, str(empty)))
						.as("%s on string '%s'", function.getURI(), empty)
						.isInstanceOf(ValueExprEvaluationException.class);
			}
		}
	}

	@Test
	void tenThousandLevelNestingIsABoundedErrorNotAStackOverflow() {
		int depth = 10_000;
		Literal arrays = json("[".repeat(depth) + "]".repeat(depth));
		Literal objects = json("{\"a\":".repeat(depth) + "1" + "}".repeat(depth));
		Literal mixed = json("[{\"a\":".repeat(depth / 2) + "1" + "}]".repeat(depth / 2));
		for (Literal document : List.of(arrays, objects, mixed)) {
			for (Function function : JSON_INPUT_FUNCTIONS) {
				// assertThatThrownBy fails on a StackOverflowError as well, since that is not the expected type
				assertThatThrownBy(() -> evaluateWithDocument(function, document))
						.as(function.getURI())
						.isInstanceOf(ValueExprEvaluationException.class)
						.hasMessageContaining("nested deeper");
			}
		}
	}

	@Test
	void duplicateObjectKeysLastValueWins() {
		// pins current behaviour: a repeated key keeps the position of its first occurrence and the last value
		Literal document = json("{\"a\":1,\"b\":2,\"a\":3}");
		assertThat(new JsonValue().evaluate(VF, document, str("$.a"))).isEqualTo(integer(3));
		assertThat(new JsonQuery().evaluate(VF, document, str("$"))).isEqualTo(json("{\"a\":3,\"b\":2}"));
		assertThat(new JsonKeys().evaluate(VF, document)).isEqualTo(json("[\"a\",\"b\"]"));
		assertThat(new JsonQuery().evaluate(VF, document, str("$..a"))).isEqualTo(json("3"));
	}

	@Test
	void numberLexicalFormsArePreservedInOutput() {
		// 1e400 stays compact (BigDecimal notation), 1.0 and 1 stay distinct, ordinary exponent doubles are
		// normalised to Java's form
		assertThat(new JsonQuery().evaluate(VF, json("[1e400,1.0,1,1.50,-1e400,1e-400]"), str("$")))
				.isEqualTo(json("[1E+400,1.0,1,1.50,-1E+400,1E-400]"));
		assertThat(new JsonQuery().evaluate(VF, json("[1E+2,2.5e-1,0e5]"), str("$")))
				.isEqualTo(json("[100.0,0.25,0.0]"));
		// pins current behaviour: the integer -0 has no sign in the JSON model and is written as 0, -0.0 as 0.0
		assertThat(new JsonQuery().evaluate(VF, json("[-0,-0.0]"), str("$"))).isEqualTo(json("[0,0.0]"));
		// and the parsed values decode as the matching RDF numeric types
		assertThat(new JsonValue().evaluate(VF, json("[1.0]"), str("$[0]")))
				.isEqualTo(VF.createLiteral(new java.math.BigDecimal("1.0")));
		assertThat(new JsonValue().evaluate(VF, json("[1]"), str("$[0]"))).isEqualTo(integer(1));
	}

	@Test
	void nonStringNonJsonLiteralIsAnEvaluationError() {
		for (Literal document : List.of(VF.createLiteral(1), VF.createLiteral(true), VF.createLiteral(1.5),
				VF.createLiteral("2024-01-01", CoreDatatype.XSD.DATE), VF.createLiteral("[1]", CoreDatatype.XSD.ANYURI),
				VF.createLiteral("[1]", VF.createIRI("urn:custom")))) {
			for (Function function : JSON_INPUT_FUNCTIONS) {
				assertThatThrownBy(() -> evaluateWithDocument(function, document))
						.as("%s on %s", function.getURI(), document)
						.isInstanceOf(ValueExprEvaluationException.class);
			}
		}
	}

	// ------------------------------------------------------------------ paths

	private static final Literal DOC = json("{\"a\":{\"b\":[10,20,30]},\"a b\":1,"
			+ "\"list\":[{\"name\":\"x\"},{\"name\":\"y\",\"nested\":{\"name\":\"z\"}}]}");

	private static final Literal ARRAY = json("[7,8,9]");

	@Test
	void everyPathFormSelectsTheExpectedNodes() {
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$"))).isEqualTo(DOC);
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$.a"))).isEqualTo(json("{\"b\":[10,20,30]}"));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$['a b']"))).isEqualTo(integer(1));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$[\"a b\"]"))).isEqualTo(integer(1));
		assertThat(new JsonValue().evaluate(VF, ARRAY, str("$[0]"))).isEqualTo(integer(7));
		assertThat(new JsonValue().evaluate(VF, ARRAY, str("$[-1]"))).isEqualTo(integer(9));
		assertThat(new JsonValue().evaluate(VF, ARRAY, str("$[-3]"))).isEqualTo(integer(7));
		assertThat(new JsonQuery().evaluate(VF, ARRAY, str("$[*]"))).isEqualTo(json("[7,8,9]"));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$..name"))).isEqualTo(json("[\"x\",\"y\",\"z\"]"));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$..b"))).isEqualTo(json("[10,20,30]"));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.a.b[1]"))).isEqualTo(integer(20));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.list[1].name"))).isEqualTo(str("y"));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$.a['b'][-1]"))).isEqualTo(integer(30));
		assertThat(new JsonValue().evaluate(VF, DOC, str("$['a']['b'][0]"))).isEqualTo(integer(10));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$.list[*].name"))).isEqualTo(json("[\"x\",\"y\"]"));
		assertThat(new JsonQuery().evaluate(VF, DOC, str("$.a.*"))).isEqualTo(json("[10,20,30]"));
		// whitespace around the path is ignored
		assertThat(new JsonValue().evaluate(VF, ARRAY, str("  $[1] "))).isEqualTo(integer(8));
	}

	@Test
	void missingKeyOrIndexIsErrorForValueAndQueryButFalseForExists() {
		for (String path : List.of("$.missing", "$.a.missing", "$.a.b[3]", "$.a.b[-4]", "$.list[2].name",
				"$..nothing", "$.a.b.c")) {
			assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, str(path)))
					.as("jsonValue %s", path)
					.isInstanceOf(ValueExprEvaluationException.class)
					.hasMessageContaining("selects no value");
			// pins current behaviour: jsonQuery raises an error for zero matches (BIND leaves the variable unbound)
			assertThatThrownBy(() -> new JsonQuery().evaluate(VF, DOC, str(path)))
					.as("jsonQuery %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThat(new JsonExists().evaluate(VF, DOC, str(path))).as("jsonExists %s", path)
					.isEqualTo(BooleanLiteral.FALSE);
		}
	}

	@Test
	void malformedPathsAreEvaluationErrorsForEveryPathFunction() {
		for (String path : List.of("$.", "$[", "$.a[?(@)]", "$..", "$.[0]", "$[1.5]", "$['unterminated]",
				"$[]", "$]", "$.a[", "$a", "$.a[0", "$..[1]")) {
			assertThatThrownBy(() -> new JsonValue().evaluate(VF, DOC, str(path)))
					.as("jsonValue %s", path)
					.isInstanceOf(ValueExprEvaluationException.class)
					.hasMessageContaining("Invalid JSON path");
			assertThatThrownBy(() -> new JsonQuery().evaluate(VF, DOC, str(path)))
					.as("jsonQuery %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
			// pins current behaviour: a malformed path is an error for jsonExists too, not false
			assertThatThrownBy(() -> new JsonExists().evaluate(VF, DOC, str(path)))
					.as("jsonExists %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new JsonKeys().evaluate(VF, DOC, str(path)))
					.as("jsonKeys %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new JsonArrayLength().evaluate(VF, DOC, str(path)))
					.as("jsonArrayLength %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new JsonSet().evaluate(VF, DOC, str(path), integer(1)))
					.as("jsonSet %s", path)
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	@Test
	void pathWithoutLeadingDollarIsImplied() {
		// pins current behaviour: a missing "$" is implied rather than rejected
		assertThat(new JsonValue().evaluate(VF, DOC, str("a.b[1]"))).isEqualTo(integer(20));
		assertThat(new JsonValue().evaluate(VF, DOC, str(".a.b[2]"))).isEqualTo(integer(30));
		assertThat(new JsonValue().evaluate(VF, ARRAY, str("[0]"))).isEqualTo(integer(7));
		assertThat(new JsonValue().evaluate(VF, DOC, str("['a b']"))).isEqualTo(integer(1));
		assertThat(new JsonQuery().evaluate(VF, DOC, str(""))).isEqualTo(DOC);
		assertThat(new JsonQuery().evaluate(VF, DOC, str("..name"))).isEqualTo(json("[\"x\",\"y\",\"z\"]"));
	}

	@Test
	void indexOnObjectAndKeyOnArrayAreNoMatchNotExceptions() {
		Literal object = json("{\"0\":\"zero\",\"a\":{\"x\":1}}");
		assertThat(new JsonExists().evaluate(VF, object, str("$[0]"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new JsonExists().evaluate(VF, object, str("$.a[0]"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new JsonExists().evaluate(VF, object, str("$.a.x.y"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new JsonExists().evaluate(VF, object, str("$.a.x[0]"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new JsonExists().evaluate(VF, ARRAY, str("$.a"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new JsonExists().evaluate(VF, ARRAY, str("$['0']"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new JsonExists().evaluate(VF, ARRAY, str("$[0].a"))).isEqualTo(BooleanLiteral.FALSE);
		// the quoted "0" is a key, the bare 0 an index: they never cross over
		assertThat(new JsonValue().evaluate(VF, object, str("$['0']"))).isEqualTo(str("zero"));
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, object, str("$[0]")))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("selects no value");
		assertThatThrownBy(() -> new JsonValue().evaluate(VF, ARRAY, str("$.a")))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("selects no value");
	}

	@Test
	void quotesInsideBracketNamesAreTakenLiterally() {
		// pins current behaviour: no SQL-style '' unescaping, the bracket content between the quotes is the key
		Literal document = json("{\"it''s\":1,\"it's\":2,\"say \\\"hi\\\"\":3}");
		assertThat(new JsonValue().evaluate(VF, document, str("$['it''s']"))).isEqualTo(integer(1));
		assertThat(new JsonValue().evaluate(VF, document, str("$[\"it's\"]"))).isEqualTo(integer(2));
		assertThat(new JsonValue().evaluate(VF, document, str("$['say \"hi\"']"))).isEqualTo(integer(3));
		assertThat(new JsonExists().evaluate(VF, json("{\"its\":1}"), str("$['it''s']")))
				.isEqualTo(BooleanLiteral.FALSE);
	}
}
